-- Wrap auth/session function calls in RLS policy predicates in (SELECT ...) so Postgres
-- evaluates them once per statement (InitPlan) instead of once per row -- the
-- Supabase-documented RLS perf pattern. Predicate-equivalent (row visibility unchanged).
-- Generated by 'pgrls fix --rule PERF001' and verified (PERF001 -> 0). Refs #195.

-- [PERF001] Wrap auth function call(s) in policy 'Anyone can view battle records or service can view any' on public.battle_records so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Anyone can view battle records or service can view any" ON public.battle_records
    USING (TRUE OR (SELECT auth.role()) = CAST('service_role' AS text) OR (SELECT auth.uid()) IS NULL);

-- [PERF001] Wrap auth function call(s) in policy 'Only service can update battle records' on public.battle_records so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Only service can update battle records" ON public.battle_records
    USING ((SELECT auth.role()) = CAST('service_role' AS text) OR (SELECT auth.uid()) IS NULL);

