ALTER POLICY "Anyone can view elo ratings or service can view any" ON public.player_elo_ratings
    USING (TRUE OR (SELECT auth.role()) = CAST('service_role' AS text) OR (SELECT auth.uid()) IS NULL);

-- [PERF001] Wrap auth function call(s) in policy 'Only service can modify elo ratings' on public.player_elo_ratings so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Only service can modify elo ratings" ON public.player_elo_ratings
    USING ((SELECT auth.role()) = CAST('service_role' AS text) OR (SELECT auth.uid()) IS NULL);

