-- [PERF001] Wrap auth function call(s) in policy 'Players can update own record or service can update any' on public.players so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Players can update own record or service can update any" ON public.players
    USING (CAST((SELECT auth.uid()) AS text) = id OR (SELECT auth.role()) = CAST('service_role' AS text) OR (SELECT auth.uid()) IS NULL);

-- [PERF001] Wrap auth function call(s) in policy 'Players can view all records or service can view any' on public.players so Postgres can cache the result for the whole statement instead of re-evaluating per row.
ALTER POLICY "Players can view all records or service can view any" ON public.players
    USING (TRUE OR (SELECT auth.role()) = CAST('service_role' AS text) OR (SELECT auth.uid()) IS NULL);
